function StatCard({ stat }) {
  return (
    <div style={{
      background:"#1e1e2e",border:"1px solid #333",borderRadius:8,
      padding:"14px 16px",flex:"1 1 200px",minWidth:200,
    }}>
      <div style={{borderBottom:"2px solid "+stat.color,paddingBottom:6,marginBottom:8}}>
        <span style={{color:stat.color,fontWeight:700,fontSize:14}}>{stat.label}</span>
        <span style={{color:"#888",fontSize:11,marginLeft:8}}>{stat.duration}</span>
      </div>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
        <thead>
          <tr>
            <th style={{textAlign:"left",color:"#888",fontWeight:400,paddingBottom:4}}>項目</th>
            <th style={{textAlign:"right",color:"#ff7675",fontWeight:400,paddingBottom:4}}>ピーク</th>
            <th style={{textAlign:"right",color:"#74b9ff",fontWeight:400,paddingBottom:4}}>最終値</th>
          </tr>
        </thead>
        <tbody>
          {stat.rows.map(r=>(
            <tr key={r.name}>
              <td style={{color:"#aaa",padding:"2px 0"}}>{r.name}</td>
              <td style={{textAlign:"right",color:"#ff7675",fontFamily:"monospace"}}>{r.peak}</td>
              <td style={{textAlign:"right",color:"#74b9ff",fontFamily:"monospace"}}>{r.final}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ── メインコンポーネント ── */
export default function AdhesionChart() {
  const [showVelocity, setShowVelocity]  = useState(true);
  const [showHeight,   setShowHeight]    = useState(true);

  const toggle = (setter) => setter(v => !v);

  return (
    <div style={{background:"#12121f",color:"#e0e0e0",fontFamily:"sans-serif",padding:"24px 32px",minHeight:"100vh"}}>
      <h2 style={{margin:"0 0 4px",fontSize:18}}>静止判定 — Adhesion 比較</h2>
      <p style={{margin:"0 0 20px",color:"#888",fontSize:13}}>
        μ=0.01 固定 · Adhesion係数 0 / 1 / 10 · frame 120 → 479
      </p>

      {/* Toggle */}
      <div style={{display:"flex",gap:10,marginBottom:20,flexWrap:"wrap"}}>
        {[
          {key:"velocity", label:"速度パネル",   setter:setShowVelocity, val:showVelocity},
          {key:"height",   label:"液面パネル", setter:setShowHeight,   val:showHeight},
        ].map(t=>(
          <button key={t.key} onClick={()=>toggle(t.setter)}
            style={{padding:"5px 14px",borderRadius:4,border:"1px solid #444",
              background:t.val?"#2d2d44":"transparent",color:t.val?"#e0e0e0":"#888",
              cursor:"pointer",fontSize:12}}>
            {t.val?"▼":"▶"} {t.label}
          </button>
        ))}
      </div>

      {/* Panel 1: RMS + Vmax */}
      {showVelocity && (
        <section style={{marginBottom:32}}>
          <h3 style={{fontSize:14,color:"#aaa",margin:"0 0 10px"}}>速度（RMS・最大）</h3>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={DATA} margin={{top:6,right:24,bottom:24,left:24}}>
              <CartesianGrid strokeDasharray="3 3" stroke="#2a2a3a"/>
              <XAxis {...XAXIS}/>
              <YAxis label={{value:"速度 (m/s)",angle:-90,position:"insideLeft",offset:8}} tick={{fontSize:11}}/>
              <Tooltip content={<TipBox/>}/>
              <Legend verticalAlign="top"/>
              <Line type="monotone" dataKey="rms_0"  name="RMS Ad=0"  stroke={CA0}  dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="rms_1"  name="RMS Ad=1"  stroke={CA1}  dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="rms_10" name="RMS Ad=10" stroke={CA10} dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="vmax_0"  name="Vmax Ad=0"  stroke={CA0}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
              <Line type="monotone" dataKey="vmax_1"  name="Vmax Ad=1"  stroke={CA1}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
              <Line type="monotone" dataKey="vmax_10" name="Vmax Ad=10" stroke={CA10} dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
            </LineChart>
          </ResponsiveContainer>
        </section>
      )}

      {/* Panel 2: 液面高さ・盛り上がり量 */}
      {showHeight && (
        <section style={{marginBottom:32}}>
          <h3 style={{fontSize:14,color:"#aaa",margin:"0 0 10px"}}>液面高さ・盛り上がり量</h3>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={DATA} margin={{top:6,right:24,bottom:24,left:24}}>
              <CartesianGrid strokeDasharray="3 3" stroke="#2a2a3a"/>
              <XAxis {...XAXIS}/>
              <YAxis label={{value:"高さ (mm)",angle:-90,position:"insideLeft",offset:8}} tick={{fontSize:11}}/>
              <Tooltip content={<TipBox/>}/>
              <Legend verticalAlign="top"/>
              <Line type="monotone" dataKey="wall_h_0"   name="壁際 Ad=0"   stroke={CA0}  dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="wall_h_1"   name="壁際 Ad=1"   stroke={CA1}  dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="wall_h_10"  name="壁際 Ad=10"  stroke={CA10} dot={false} isAnimationActive={false} strokeWidth={1.5} connectNulls={false}/>
              <Line type="monotone" dataKey="center_h_0"  name="中心 Ad=0"   stroke={CA0}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
              <Line type="monotone" dataKey="center_h_1"  name="中心 Ad=1"   stroke={CA1}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
              <Line type="monotone" dataKey="center_h_10" name="中心 Ad=10"  stroke={CA10} dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="4 2" connectNulls={false}/>
              <Line type="monotone" dataKey="rise_0"  name="盛り上がり Ad=0"   stroke={CA0}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="2 3" connectNulls={false}/>
              <Line type="monotone" dataKey="rise_1"  name="盛り上がり Ad=1"   stroke={CA1}  dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="2 3" connectNulls={false}/>
              <Line type="monotone" dataKey="rise_10" name="盛り上がり Ad=10"  stroke={CA10} dot={false} isAnimationActive={false} strokeWidth={1.5} strokeDasharray="2 3" connectNulls={false}/>
            </LineChart>
          </ResponsiveContainer>
        </section>
      )}

      {/* 統計カード */}
      <div style={{display:"flex",gap:16,flexWrap:"wrap",marginTop:8}}>
        {STATS.map(s=><StatCard key={s.label} stat={s}/>)}
      </div>

      {/* フッターノート */}
      <p style={{marginTop:20,color:"#555",fontSize:11}}>
        実線=RMS速度 / 壁際液面高さ　破線=最大速度 / 中心液面高さ　点線=盛り上がり量
        &ensp;|&ensp; ピーク値（赤）→ 最終値（青）&ensp;|&ensp; 全条件 frame 120 → 479
      </p>
    </div>
  );
}
